// Estrae e formatta il messaggio Telegram
const msg = $json.message || {};
const text = msg.text || '[messaggio senza testo]';
const from = msg.from?.first_name || msg.from?.username || 'Sconosciuto';
const date = new Date().toLocaleString('it-IT', {
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
});

return {
  formattedText: `[${date}] ${from}: ${text}`,
  messageText: text,
  from: from,
  date: date
};
